import {Component, OnDestroy} from '@angular/core';
import {CreateTaskComponent} from "../create-task/create-task.component";
import {AsyncPipe} from "@angular/common";
import {Subject} from "rxjs";
import {TaskService} from "../../services/task.service";
import {Router} from "@angular/router";

@Component({
  selector: 'app-task-list',
  standalone: true,
  imports: [
    CreateTaskComponent,
    AsyncPipe
  ],
  templateUrl: './task-list.component.html',
  styleUrl: './task-list.component.scss'
})
export class TaskListComponent implements OnDestroy {
  destroy$: Subject<void> = new Subject<void>();

  constructor(protected taskService: TaskService, private router: Router) {
  }

  removeTask(taskId: number): void {
    this.taskService.removeTask(taskId);
  }

  viewTask(taskId: number): void {
    this.router.navigate(['/task-list', taskId]);
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }
}
<div class="list-container">
  @if (taskService.tasks$) {
    <ul>
      @for (task of taskService.tasks$ | async; track task; let idx = $index) {
        <li>
          <div class="task-card">
            <p (click)="viewTask(task.id)">{{ task.title }}</p>
            <p>{{ task.description }}</p>
            <p>{{ task.type }}</p>
            <p>{{ task.createdOn }}</p>
            <p>{{ task.status }}</p>
            <button (click)="removeTask(idx)">
              <svg class="h-8 w-8 text-red-500" width="24" height="24" viewBox="0 0 24 24" stroke-width="2"
                   stroke="currentColor" fill="none" stroke-linecap="round" stroke-linejoin="round">
                <path stroke="none" d="M0 0h24v24H0z"/>
                <line x1="4" y1="7" x2="20" y2="7"/>
                <line x1="10" y1="11" x2="10" y2="17"/>
                <line x1="14" y1="11" x2="14" y2="17"/>
                <path d="M5 7l1 12a2 2 0 0 0 2 2h8a2 2 0 0 0 2 -2l1 -12"/>
                <path d="M9 7v-3a1 1 0 0 1 1 -1h4a1 1 0 0 1 1 1v3"/>
              </svg>
            </button>
          </div>
        </li>
      }
    </ul>
  }
</div>
